import type { Comment, Post } from '../../../lib/types'

type BlogPostProps = { params: Promise<{ id: string }> }

export const revalidate = 300
// Leave dynamicParams enabled to preserve the old blocking fallback for other IDs.

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const response = await fetch('https://jsonplaceholder.typicode.com/posts')
  if (!response.ok) throw new Error('Failed to load post paths')
  const posts: Post[] = await response.json()
  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }))
}

async function getPost(id: string): Promise<Post> {
  const response = await fetch(`https://jsonplaceholder.typicode.com/posts/${encodeURIComponent(id)}`, {
    next: { revalidate: 300 },
  })
  if (!response.ok) {
    if (response.status === 404) notFound()
    throw new Error('Failed to load post')
  }
  return response.json() as Promise<Post>
}

