import { NextResponse } from 'next/server'
import type { ApiPost } from '../../../lib/types'

export function GET(): NextResponse<ApiPost[]> {
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]
  return NextResponse.json(posts)
}

export async function POST(request: Request): Promise<NextResponse<ApiPost | { error: string }>> {
  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }
  if (!body || typeof body !== 'object' || !('title' in body) || !('content' in body) ||
      typeof body.title !== 'string' || typeof body.content !== 'string' ||
      !body.title || !body.content) {
    return NextResponse.json({ error: 'Title and content are required' }, { status: 400 })
  }

  const post: ApiPost = {
    id: Date.now(),
    title: body.title,
    content: body.content,
    createdAt: new Date().toISOString(),
  }
  return NextResponse.json(post, { status: 201 })
}
