  return NextResponse.json({
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  })
}

export async function PUT(request: Request, { params }: PostContext): Promise<NextResponse<ApiPost | { error: string }>> {
  const { id } = await params
  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return NextResponse.json({ error: 'Invalid post' }, { status: 400 })
  }
  const title = 'title' in body && typeof body.title === 'string' ? body.title : undefined
  const content = 'content' in body && typeof body.content === 'string' ? body.content : undefined
  return NextResponse.json({
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  })
}

export async function DELETE(_request: Request, { params }: PostContext): Promise<NextResponse<{ message: string }>> {
  const { id } = await params
  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}
